/**
 * Funciones compartidas por todas las páginas.
 *
 * Este archivo se carga antes que el JS de cada página (Index.min.js, Home.min.js),
 * así esas páginas pueden usar postJson(), formToObject() y alertDialog().
 * El nombre termina en ".min.js" por costumbre del proyecto, pero no está minificado.
 */

/**
 * Envía `payload` como JSON a `url` (petición POST) y devuelve la respuesta del servidor
 * ya convertida en objeto, por ejemplo {code: 0} o {code: 1, title: 'FAILED!', message: '...'}.
 * Si falla la conexión o el servidor no responde JSON, devuelve un error normal.
 *
 * Uso: const data = await postJson('post.php', {action: 'like', post_id: 5});
 */
async function postJson(url, payload) {
    try {
        const response = await fetch(url, {
            method: 'POST',
            cache: 'no-cache',
            // El servidor rechaza las peticiones que no digan que son JSON (Controller::readJson).
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify(payload)
        });

        // 401 = la sesión se cerró: volvemos al login.
        if (response.status === 401) {
            window.location.href = 'index.php';
        }

        return await response.json();
    } catch (error) {
        return {code: 1, title: 'FAILED!', message: 'Something went wrong, please try again'};
    }
}

/**
 * Convierte los campos de un formulario en un objeto: {email: '...', pass: '...'}.
 * La clave de cada campo es su atributo "name".
 */
function formToObject(form) {
    return Object.fromEntries(new FormData(form));
}

let alertTimeout;

/**
 * Muestra la alerta roja de App/View/Alert.view.php durante 3 segundos.
 */
function alertDialog(title, message) {
    const alertDiv = document.querySelector('.alert');
    // textContent (y no innerHTML) muestra el texto tal cual, sin interpretar HTML.
    alertDiv.querySelector('strong').textContent = title;
    alertDiv.querySelector('p').textContent = message;
    alertDiv.classList.add('display-alert');

    // Si ya había una alerta, reiniciamos la cuenta de 3 segundos.
    clearTimeout(alertTimeout);
    alertTimeout = setTimeout(() => alertDiv.classList.remove('display-alert'), 3000);
}

// La "x" de la alerta la cierra. El "?." evita un error en páginas sin alerta.
document.querySelector('.alert .closebtn')?.addEventListener('click', () => {
    document.querySelector('.alert').classList.remove('display-alert');
});
